def solve(rows):
    kept_rows = []
    state = 0
    original_index = 0

    for row in rows:
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str):
            if '|' in row:
                weight = int(row.split('|')[1])
            else:
                weight = 0
        elif isinstance(row, list):
            weight = sum(field for field in row if not isinstance(field, bool)) + sum(len(s) for s in row if isinstance(s, str))
        else:
            weight = 0

        if (state + weight + original_index) % 7 != 5 or original_index == len(rows) - 1:
            kept_rows.append(row)
            state = 0 if weight == 0 else (3 * state + weight) % 7
            original_index += 1

    if not kept_rows:
        return []

    eligible_days = []
    for row in kept_rows:
        if isinstance(row, list) and len(row) == 2 and not row[1]:
            day = row[0]
            if day % 7 != 0:
                eligible_days.append(day)

    distinct_days = sorted(list(set(eligible_days)), key=lambda x: x)
    return distinct_days[:4]

